{
  "packet_id": "H6-T02-1",
  "claim_id": "C048",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C048",
    "value": "Rare-delay testing requires sufficient trials because observing no slow export in a small sample cannot establish goodness.",
    "scope": "Sample-size limitation on favorable classification; no sufficient sample size is specified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P028",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P028 directly states both the trial requirement and the insufficiency of observing no slow export in a small sample."
    }
  },
  "signal_basis": {
    "component_id": "C048_SIGNAL",
    "value": "Observe each revision's trial count, fraction of exports exceeding one hour and uncertainty. Classify it as good only when prespecified evidence supports the acceptable range, using a predetermined replication and repeated-testing rule.",
    "scope": "Per-revision tail-rate classification, with workload and load recorded and inconclusive classification when evidence is inadequate.",
    "provenance": {
      "refs": [
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the observations, evidence-based classification and control of repeated-testing error."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C048_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The supported sampling limitation requires no unresolved empirical relation."
    }
  },
  "rationale": "A small sample can contain no slow exports even when the underlying tail rate is unacceptable. Thus absence alone does not establish goodness; favorable classification requires sufficient evidence against the prespecified rate criterion. This licenses the claim's stated sample-size limitation.",
  "uncertainty": "The required trial count depends on the acceptable rate and confidence criteria; the claim specifies no numerical minimum.",
  "anomalies": []
}
